// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [3087210949, 886794693, 1727187397, 634544581, 1752144325, 2664014277, 1122906565, 2467490245, 2064396741, 296911301, 1313589701, 302475717, 1931606469, 3663929797, 4225298885, 4094845381];
const blocks = ["NFC U+030000-U+030FFF", "NFC U+031000-U+031FFF", "NFC U+032000-U+032FFF", "NFC U+033000-U+033FFF", "NFC U+034000-U+034FFF", "NFC U+035000-U+035FFF", "NFC U+036000-U+036FFF", "NFC U+037000-U+037FFF", "NFC U+038000-U+038FFF", "NFC U+039000-U+039FFF", "NFC U+03A000-U+03AFFF", "NFC U+03B000-U+03BFFF", "NFC U+03C000-U+03CFFF", "NFC U+03D000-U+03DFFF", "NFC U+03E000-U+03EFFF", "NFC U+03F000-U+03FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 196608 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFC");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
